import { Component, Input } from '@angular/core';
import { WeeklyStats } from '../../models/health-data.model';

@Component({
  selector: 'app-weekly-progress',
  templateUrl: './weekly-progress.component.html',
  styleUrls: ['./weekly-progress.component.scss']
})
export class WeeklyProgressComponent {
  @Input() weeklyStats: WeeklyStats | null = null;

  formatValue(value: number): string {
    return value.toLocaleString();
  }

  roundValue(value: number): number {
    return Math.round(value);
  }
}
<div class="grid grid-cols-2 gap-4">
  <div class="stat-card">
    <div class="text-2xl font-bold text-cyan mb-1">{{ formatValue(weeklyStats?.totalSteps || 0) }}</div>
    <div class="text-sm text-grey">Total Steps</div>
  </div>
  <div class="stat-card">
    <div class="text-2xl font-bold text-cyan mb-1">{{ formatValue(weeklyStats?.totalCalories || 0) }}</div>
    <div class="text-sm text-grey">Total Calories</div>
  </div>
  <div class="stat-card">
    <div class="text-2xl font-bold text-cyan mb-1">{{ weeklyStats?.daysTracked || 0 }}</div>
    <div class="text-sm text-grey">Days Tracked</div>
  </div>
  <div class="stat-card">
    <div class="text-2xl font-bold text-cyan mb-1">{{ formatValue((weeklyStats?.totalSteps || 0) / (weeklyStats?.daysTracked || 1)) }}</div>
    <div class="text-sm text-grey">Avg Steps/Day</div>
  </div>
</div>
